mapper.select:
SELECT D.WEEK,D.A_OVER,D.B_OVER,D.C_OVER,D.D_OVER,D.ABCD_OVER,D.DAY_OVER_AVG,D.FCST_OVER_DAY ,CASE WHEN D.WEEK LIKE 'Y%' THEN NULL ELSE D.DAY_OVER_ACC END DAY_OVER_ACC ,D.TARGET_DAY_ACC ,CASE WHEN (D.WEEK LIKE 'Y%' OR D.WEEK<TO_CHAR(SYSDATE-8/24-2/1440,'YYYYMMDD')) THEN NVL(D.ABCD_OVER,0)+NVL(D.FCST_OVER_DAY,0) ELSE NULL END TOTAL_OVER FROM ( SELECT A1.WEEK,A2.A_OVER,A2.B_OVER,A2.C_OVER,A2.D_OVER,A2.ABCD_OVER ,NULL DAY_OVER_AVG,NULL FCST_OVER_DAY,NULL DAY_OVER_ACC,2100 TARGET_DAY_ACC FROM ( SELECT DISTINCT WEEK FROM (SELECT A.*,DENSE_RANK() OVER(ORDER BY A.WEEK DESC) RN FROM (SELECT 'Y'||SUBSTR(SHOP_WEEK,3,2)||'W'||SUBSTR(SHOP_WEEK,5,2) WEEK,SHIFT_DATE FROM ODS.WP_CALENDAR WHERE SHIFT_HOUR='01' AND SHIFT_DATE <= TO_CHAR(SYSDATE-1-8/24-2/1440,'YYYYMMDD'))A ) WHERE RN <= 5 AND RN>=2 )A1 ,( SELECT B.WEEK ,SUM(CASE WHEN A.QT_GRADE='A' THEN WAFER_QTY ELSE 0 END) A_OVER ,SUM(CASE WHEN A.QT_GRADE='B' THEN WAFER_QTY ELSE 0 END) B_OVER ,SUM(CASE WHEN A.QT_GRADE='C' THEN WAFER_QTY ELSE 0 END) C_OVER ,SUM(CASE WHEN A.QT_GRADE='D' THEN WAFER_QTY ELSE 0 END) D_OVER ,SUM(CASE WHEN A.QT_GRADE IN ('A','B','C','D') THEN WAFER_QTY ELSE 0 END) ABCD_OVER FROM (SELECT * FROM A1MFG.QTIME_OVER_DAILY WHERE SHIFT_DATE <>TO_CHAR(SYSDATE-8/24-2/1440,'YYYYMMDD')
AND NENG_FLAG LIKE '%'
AND NENG_FLAG=#{nengflag}
AND (MODULE LIKE '%' OR MODULE IS NULL)
AND SUBSTR(CURRENT_OPE_NO,5,1)='Q'
AND MODULE=#{module}
AND TECH LIKE '%'
AND TECH =#{tech}
AND CROSS_FLAG='N' AND QT_CONCERN='Y')A ,(SELECT WEEK,SHIFT_DATE FROM (SELECT A.*,DENSE_RANK() OVER(ORDER BY A.WEEK DESC) RN FROM (SELECT 'Y'||SUBSTR(SHOP_WEEK,3,2)||'W'||SUBSTR(SHOP_WEEK,5,2) WEEK,SHIFT_DATE FROM ODS.WP_CALENDAR WHERE SHIFT_HOUR='01' AND SHIFT_DATE <= TO_CHAR(SYSDATE-1-8/24-2/1440,'YYYYMMDD'))A ) WHERE RN <= 5 AND RN>=2)B WHERE A.SHIFT_DATE=B.SHIFT_DATE GROUP BY B.WEEK )A2 WHERE A1.WEEK=A2.WEEK(+)
UNION ALL
SELECT NVL(WEEK ,(SELECT 'Y'||SUBSTR(SHOP_WEEK,3,2)||'W'||SUBSTR(SHOP_WEEK,5,2) WEEK FROM ODS.WP_CALENDAR WHERE SHIFT_HOUR='01' AND SHIFT_DATE = TO_CHAR(SYSDATE-1-8/24-2/1440,'YYYYMMDD'))) WEEK ,SUM(A_OVER) A_OVER,SUM(B_OVER) B_OVER,SUM(C_OVER) C_OVER,SUM(D_OVER) D_OVER,SUM(ABCD_OVER) ABCD_OVER ,AVG(DAY_OVER_AVG) DAY_OVER_AVG,SUM(FCST_OVER_DAY) FCST_OVER_DAY,MAX(DAY_OVER_ACC) DAY_OVER_ACC,MAX(TARGET_DAY_ACC) TARGET_DAY_ACC
FROM
(SELECT A4.* ,CASE WHEN A4.WEEK NOT LIKE 'Y%' AND A4.ABCD_OVER IS NULL AND A4.WEEK>=TO_CHAR(SYSDATE-8/24-2/1440,'YYYYMMDD') THEN A4.DAY_OVER_AVG ELSE NULL END FCST_OVER_DAY ,SUM(CASE WHEN A4.WEEK LIKE 'Y%' THEN NULL ELSE NVL(A4.ABCD_OVER,A4.DAY_OVER_AVG) END) OVER(ORDER BY REPLACE(A4.WEEK,'Y','1')) DAY_OVER_ACC ,SUM(TARGET_DAY) OVER(ORDER BY REPLACE(A4.WEEK,'Y','1')) TARGET_DAY_ACC FROM (
SELECT A3.* ,ROUND(AVG(CASE WHEN A3.WEEK LIKE 'Y%' THEN NULL ELSE A3.ABCD_OVER END) OVER()) DAY_OVER_AVG ,ROUND(2100/7) TARGET_DAY FROM (
SELECT A1.SHIFT_DATE WEEK--,A2.A_OVER,A2.B_OVER,A2.C_OVER,A2.D_OVER,A2.ABCD_OVER ,CASE WHEN A1.SHIFT_DATE<TO_CHAR(SYSDATE-8/24-2/1440,'YYYYMMDD') AND A2.A_OVER IS NULL THEN 0 ELSE A2.A_OVER END A_OVER ,CASE WHEN A1.SHIFT_DATE<TO_CHAR(SYSDATE-8/24-2/1440,'YYYYMMDD') AND A2.B_OVER IS NULL THEN 0 ELSE A2.B_OVER END B_OVER ,CASE WHEN A1.SHIFT_DATE<TO_CHAR(SYSDATE-8/24-2/1440,'YYYYMMDD') AND A2.C_OVER IS NULL THEN 0 ELSE A2.C_OVER END C_OVER ,CASE WHEN A1.SHIFT_DATE<TO_CHAR(SYSDATE-8/24-2/1440,'YYYYMMDD') AND A2.D_OVER IS NULL THEN 0 ELSE A2.D_OVER END D_OVER ,CASE WHEN A1.SHIFT_DATE<TO_CHAR(SYSDATE-8/24-2/1440,'YYYYMMDD') AND A2.ABCD_OVER IS NULL THEN 0 ELSE A2.ABCD_OVER END ABCD_OVER FROM ( SELECT C.WEEK,C.SHIFT_DATE FROM (SELECT 'Y'||SUBSTR(SHOP_WEEK,3,2)||'W'||SUBSTR(SHOP_WEEK,5,2) WEEK ,SHIFT_DATE FROM ODS.WP_CALENDAR WHERE SHIFT_HOUR='01')C ,(SELECT 'Y'||SUBSTR(SHOP_WEEK,3,2)||'W'||SUBSTR(SHOP_WEEK,5,2) WEEK,SHIFT_DATE FROM ODS.WP_CALENDAR WHERE SHIFT_HOUR='01' AND SHIFT_DATE=TO_CHAR(SYSDATE-1-8/24-2/1440,'YYYYMMDD'))D WHERE C.WEEK=D.WEEK )A1 ,( SELECT A.SHIFT_DATE ,SUM(CASE WHEN A.QT_GRADE='A' THEN WAFER_QTY ELSE 0 END) A_OVER ,SUM(CASE WHEN A.QT_GRADE='B' THEN WAFER_QTY ELSE 0 END) B_OVER ,SUM(CASE WHEN A.QT_GRADE='C' THEN WAFER_QTY ELSE 0 END) C_OVER ,SUM(CASE WHEN A.QT_GRADE='D' THEN WAFER_QTY ELSE 0 END) D_OVER ,SUM(CASE WHEN A.QT_GRADE IN ('A','B','C','D') THEN WAFER_QTY ELSE 0 END) ABCD_OVER FROM (SELECT * FROM A1MFG.QTIME_OVER_DAILY WHERE SHIFT_DATE <>TO_CHAR(SYSDATE-8/24-2/1440,'YYYYMMDD')
AND NENG_FLAG LIKE '%'
AND NENG_FLAG=#{nengflag}
AND (MODULE LIKE '%' OR MODULE IS NULL)
AND SUBSTR(CURRENT_OPE_NO,5,1)='Q'
AND MODULE=#{module}
AND TECH LIKE '%'
AND TECH =#{tech}
AND CROSS_FLAG='N' AND QT_CONCERN='Y')A ,(SELECT C.WEEK,C.SHIFT_DATE FROM (SELECT 'Y'||SUBSTR(SHOP_WEEK,3,2)||'W'||SUBSTR(SHOP_WEEK,5,2) WEEK ,SHIFT_DATE FROM ODS.WP_CALENDAR WHERE SHIFT_HOUR='01')C ,(SELECT 'Y'||SUBSTR(SHOP_WEEK,3,2)||'W'||SUBSTR(SHOP_WEEK,5,2) WEEK,SHIFT_DATE FROM ODS.WP_CALENDAR WHERE SHIFT_HOUR='01' AND SHIFT_DATE=TO_CHAR(SYSDATE-1-8/24-2/1440,'YYYYMMDD'))D WHERE C.WEEK=D.WEEK)B WHERE A.SHIFT_DATE=B.SHIFT_DATE GROUP BY A.SHIFT_DATE )A2 WHERE A1.SHIFT_DATE=A2.SHIFT_DATE(+)
)A3
)A4) GROUP BY ROLLUP(WEEK))D ORDER BY REPLACE(D.WEEK,'Y','1')

SELECT A.*,B.ACLASS FROM ( SELECT WEEK,PRODG1,LOT_ID,OVER_TIME,SHIFT_DATE,WAFER_QTY,MODULE,CURRENT_OPE_NO OPE_NO ,QT_GRADE GRADE,QTIME_SPEC SPEC,RESPONSE_MODULE,MAJOR_REASON,OVER_COMMENT ,PLATFORM,PRODSPEC_ID,NENG_FLAG,TARGET_TIME,END_TIME,LOOP1,LOOP2,QT_CONCERN,SUB_LOT_TYPE ,LOT_FAB,OVER_FAB,ACTION,REMARK,INSERT_TIME,CLAIM_TIME ,CURRENT_MAINPD_ID,TECH,TARGET_MODULE,MFG_OVER,TRIGGER_OPE_NO,TARGET_OPE_NO,FLOW_KEY FROM
( SELECT A1.WEEK,A1.PRODG1,A1.LOT_ID,A1.OVER_TIME,A1.SHIFT_DATE,A1.WAFER_QTY,A1.MODULE,A1.CURRENT_OPE_NO ,A1.QT_GRADE ,A1.QTIME_SPEC ,NVL(A1.RESPONSE_MODULE,A2.RESPONSE_MODULE) RESPONSE_MODULE ,NVL(A1.MAJOR_REASON,A2.MAJOR_REASON)MAJOR_REASON ,NVL(A1.OVER_COMMENT,A2.OVER_COMMENT) OVER_COMMENT ,A1.PLATFORM,A1.PRODSPEC_ID,A1.NENG_FLAG,A1.TARGET_TIME,A1.END_TIME,A1.LOOP1,A1.LOOP2,A1.QT_CONCERN,A1.SUB_LOT_TYPE ,A1.LOT_FAB,A1.OVER_FAB,A1.ACTION,NVL(A1.REMARK,A2.REMARK) REMARK,A1.INSERT_TIME,A1.CLAIM_TIME ,A1.CURRENT_MAINPD_ID,A1.TECH,A1.TARGET_MODULE,A2.MFG_OVER,A1.CROSS_FLAG ,A1.TRIGGER_OPE_NO,A1.TARGET_OPE_NO,A1.FLOW_KEY FROM A1MFG.QTIME_OVER_DAILY A1 LEFT JOIN A1MFG.QTIME_OVER_DAILY_COMM A2 ON A1.SHIFT_DATE=A2.SHIFT_DATE AND A1.LOT_ID=A2.LOT_ID AND A1.CURRENT_OPE_NO=A2.CURRENT_OPE_NO )
WHERE CROSS_FLAG='N' AND QT_CONCERN='Y' AND 1=1 AND SHIFT_DATE BETWEEN #{startdate} AND #{enddate}
AND NENG_FLAG LIKE '%'
AND NENG_FLAG=#{nengflag}
AND (MODULE LIKE '%' OR MODULE IS NULL)
AND SUBSTR(CURRENT_OPE_NO,5,1)='Q'
AND MODULE IN ('WET','CMP')
AND MODULE=#{module}
AND TECH LIKE '%'
AND TECH =#{tech}
AND (TARGET_MODULE LIKE '%' OR TARGET_MODULE IS NULL)
AND SUBSTR(TARGET_OPE_NO,5,1)='Q'
AND TARGET_MODULE IN ('WET','CMP')
AND TARGET_MODULE=#{targetmodule}
)A ,( SELECT SHIFT_DATE,SHIFT,AB_SHIFT,'42'||DECODE(SHIFT,'D','日','N','夜')||SUBSTR(AB_SHIFT,1,1)||'班' ACLASS ,STARTDATETM STARTDATETM,ENDDATETM ENDDATETM FROM ODS.WP_CALENDAR WHERE SHIFT_DATE BETWEEN #{startdate} AND #{enddate} )B WHERE A.CLAIM_TIME>=B.STARTDATETM AND A.CLAIM_TIME<=B.ENDDATETM ORDER BY A.SHIFT_DATE DESC,A.INSERT_TIME DESC
